export const PRIVACY = "<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\">\n<link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect width='100' height='100' rx='22.5' fill='%23101C40'/><path d='M41.91 24.45A29 29 0 1 0 75.55 58.09A24 24 0 0 1 41.91 24.45Z' fill='%23F4F1EA'/><path d='M62.6 21.4A17 17 0 0 1 78.6 37.4' stroke='%23FFB547' stroke-width='4' stroke-linecap='round' fill='none'/><circle cx='63' cy='37' r='7' fill='%23FFB547'/></svg>\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,minimum-scale=1,viewport-fit=cover\">\n<title>隐私政策 · 路由器面板</title>\n<meta name=\"description\" content=\"路由器面板托管服务存了哪些数据、存多久、交给了谁、怎么删除。\">\n<style>:root{--bg:#eef1f8;--card:rgba(255,255,255,.66);--card2:rgba(255,255,255,.55);--text:#0b0b0f;--muted:#6e6e73;--line:rgba(60,60,67,.14);--fill:rgba(118,118,128,.14);--brand:#007aff;--ok:#34c759;--danger:#ff3b30;--warn:#ff9500;--shadow:inset 0 0 0 .5px rgba(255,255,255,.65),0 8px 28px rgba(31,38,80,.08);color-scheme:light}\n@media(prefers-color-scheme:dark){:root{--bg:#0b1024;--card:rgba(28,28,32,.58);--card2:rgba(72,72,80,.36);--text:#f5f5f7;--muted:#98989f;--line:rgba(255,255,255,.1);--fill:rgba(118,118,128,.26);--brand:#0a84ff;--ok:#30d158;--danger:#ff453a;--shadow:inset 0 0 0 .5px rgba(255,255,255,.09),0 8px 28px rgba(0,0,0,.28);color-scheme:dark}}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;min-height:100vh;color:var(--text);font:15px/1.55 -apple-system,BlinkMacSystemFont,\"SF Pro Text\",\"PingFang SC\",\"Noto Sans SC\",\"Microsoft YaHei\",system-ui,sans-serif;-webkit-font-smoothing:antialiased;background:var(--bg)}\nbody::before{content:\"\";position:fixed;inset:-40px;z-index:-1;filter:blur(20px);background:radial-gradient(60% 50% at 12% 8%,#c3d2ff 0,transparent 70%),radial-gradient(55% 45% at 92% 18%,#f6cdf0 0,transparent 70%),radial-gradient(70% 55% at 30% 95%,#b8ecff 0,transparent 70%),radial-gradient(50% 40% at 85% 80%,#d9ccff 0,transparent 70%),var(--bg)}\n@media(prefers-color-scheme:dark){body::before{background:radial-gradient(55% 45% at 15% 10%,#3a2c8f 0,transparent 70%),radial-gradient(50% 45% at 90% 25%,#13527a 0,transparent 70%),radial-gradient(70% 55% at 40% 100%,#4b1e6b 0,transparent 70%),#0b1024}}\na{color:var(--brand);text-decoration:none;font-weight:600}\nbutton,input,select{font:inherit;color:inherit}\nbutton{border:0;cursor:pointer}\n.wrap{max-width:960px;margin:auto;padding:16px 16px 60px}\n.top{position:sticky;top:8px;z-index:10;display:flex;align-items:center;justify-content:space-between;gap:10px;margin:8px 0 18px;padding:10px 14px;border-radius:22px;background:color-mix(in srgb,var(--bg) 82%,transparent);-webkit-backdrop-filter:saturate(180%) blur(24px);backdrop-filter:saturate(180%) blur(24px);box-shadow:var(--shadow)}\n.logo{display:flex;align-items:center;gap:10px;font-weight:700;font-size:17px;color:var(--text)}\n.logo i{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;background:#101C40;color:#fff;font-style:normal;font-size:18px;overflow:hidden;box-shadow:inset 0 0 0 .5px rgba(255,255,255,.18)}.logo i svg{width:100%;height:100%;display:block}\n.card{background:var(--card);border-radius:22px;padding:18px;box-shadow:var(--shadow);min-width:0}\n.muted{color:var(--muted)}\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:10px 18px;border-radius:99px;background:var(--fill);color:var(--text);font-weight:650;font-size:15px;transition:transform .15s,opacity .2s;white-space:nowrap}\n.btn:active{transform:scale(.96)}.btn:disabled{opacity:.5}\n.btn.primary{background:var(--brand);color:#fff}.btn.danger{color:var(--danger)}.btn.sm{padding:7px 13px;font-size:13.5px}\n.input{width:100%;padding:12px 14px;border-radius:14px;border:0;background:var(--fill);outline:0;font-size:16px;min-width:0}\n.input:focus{box-shadow:0 0 0 3px rgba(0,122,255,.25)}\n.input::placeholder{color:var(--muted);opacity:.7}\nlabel.f{display:block;margin:12px 0 6px;font-size:13px;font-weight:600;color:var(--muted)}\n.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}\n.notice{padding:11px 13px;border-radius:14px;background:var(--fill);font-size:13.5px;color:var(--muted);line-height:1.6}\n.err{color:var(--danger);font-size:13.5px;min-height:20px;margin-top:8px}\n.toast{position:fixed;left:0;right:0;top:16px;margin:auto;width:max-content;max-width:calc(100% - 32px);padding:10px 16px;border-radius:18px;background:var(--card);-webkit-backdrop-filter:blur(24px);backdrop-filter:blur(24px);box-shadow:var(--shadow),0 10px 30px rgba(0,0,0,.15);font-weight:600;font-size:14px;z-index:99;transition:opacity .3s,transform .3s}\n.toast.hide{opacity:0;transform:translateY(-10px);pointer-events:none}\n.hidden{display:none!important}\n.dot{width:9px;height:9px;border-radius:50%;background:#aaa;display:inline-block;flex:none}.dot.on{background:var(--ok)}.dot.off{background:var(--danger)}\nh1,h2,h3{letter-spacing:-.02em;margin:0}\n\n/* 顶栏上面那一条：往上滚的内容在这里淡出，不会从顶栏上方露出来 */\nbody::after{content:\"\";position:fixed;left:0;right:0;top:0;height:calc(env(safe-area-inset-top) + 34px);z-index:9;pointer-events:none;background:linear-gradient(var(--bg) 45%,color-mix(in srgb,var(--bg) 0%,transparent))}\nh2,.sech{scroll-margin-top:90px}\n/* 反馈进度条：反馈成功 → 开发人员已收到 → 已修复 / 无法修复（只显示这三段，补充说明写在下面） */\n.fsteps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin:6px 0 4px}\n.fsteps>div{position:relative;display:flex;flex-direction:column;align-items:center;text-align:center;min-width:0}\n.fsteps>div+div::before{content:'';position:absolute;top:10px;right:calc(50% + 15px);width:calc(100% - 30px);height:3px;border-radius:2px;background:var(--line)}\n.fsteps>div.on::before{background:var(--ok)}.fsteps>div.bad::before{background:var(--danger)}\n.fsteps i{width:23px;height:23px;border-radius:50%;display:grid;place-items:center;font-style:normal;font-size:12px;font-weight:700;background:var(--fill);color:var(--muted)}\n.fsteps .on i{background:var(--ok);color:#fff}.fsteps .bad i{background:var(--danger);color:#fff}\n.fsteps .cur i{box-shadow:0 0 0 4px color-mix(in srgb,var(--ok) 22%,transparent)}.fsteps .bad.cur i{box-shadow:0 0 0 4px color-mix(in srgb,var(--danger) 22%,transparent)}\n.fsteps b{display:block;font-size:12.5px;font-weight:600;margin-top:7px;line-height:1.3;word-break:keep-all}\n.fsteps .off b{color:var(--muted);font-weight:500}.fsteps .bad b{color:var(--danger)}\n\n.doc h1{font-size:28px;margin:18px 0 4px}.doc .sub{color:var(--muted);font-size:13.5px;margin:0 0 18px}\n.doc h2{font-size:19px;margin:28px 0 10px}.doc p,.doc li{font-size:14.5px;line-height:1.8}.doc ul{padding-left:20px;margin:6px 0}\ntable{width:100%;border-collapse:collapse;font-size:13.5px}td,th{padding:9px 6px;border-bottom:.5px solid var(--line);text-align:left;vertical-align:top;line-height:1.65}th{color:var(--muted);font-weight:600;white-space:nowrap}\n@media(max-width:600px){.tw table,.tw tbody,.tw tr,.tw td{display:block}.tw tr:first-child{display:none}.tw tr{padding:10px 0;border-bottom:.5px solid var(--line)}.tw tr:last-child{border-bottom:0}.tw td{border:0;padding:2px 4px}.tw td:first-child{font-weight:700;font-size:15px}.tw td:nth-child(3){color:var(--muted);font-size:12.5px}.tw td:nth-child(3)::before{content:\"存多久：\"}}\nfooter{margin-top:40px;text-align:center;color:var(--muted);font-size:13px}\n</style></head><body><div class=\"wrap doc\">\n<div class=\"top\"><a class=\"logo\" href=\"/\"><i><svg viewBox=\"0 0 100 100\" fill=\"none\" aria-hidden=\"true\"><path d=\"M41.91 24.45A29 29 0 1 0 75.55 58.09A24 24 0 0 1 41.91 24.45Z\" fill=\"#F4F1EA\"/><path d=\"M62.6 21.4A17 17 0 0 1 78.6 37.4\" stroke=\"#FFB547\" stroke-width=\"4\" stroke-linecap=\"round\" fill=\"none\"/><circle cx=\"63\" cy=\"37\" r=\"7\" fill=\"#FFB547\"/></svg></i>路由器面板</a><div class=\"row\"><a class=\"btn sm\" href=\"/security\">安全说明</a><a class=\"btn sm primary\" href=\"/app\">登录</a></div></div>\n\n<h1>隐私政策</h1>\n<p class=\"sub\">适用于托管服务（本网站和它开通的专属网址）。最后更新：2026 年 11 月 14 日</p>\n\n<div class=\"card\"><p style=\"margin:0\">一句话：<b>路由器的设置和上网情况留在你的路由器上</b>；托管服务存的是让服务跑起来必需的东西（账号、路由器登记、运行状态、推送订阅），以及你主动开启或提交的东西（云端备份、问题反馈）。你的上网记录不会上传。自己搭建（用自己的 Cloudflare）的，数据都在你自己的账号里，这份政策不适用。</p></div>\n\n<h2>存了哪些数据、存多久</h2>\n<div class=\"card tw\"><table>\n\t<tr><th>数据</th><th>里面有什么、用来做什么</th><th>存多久</th></tr>\n\t<tr><td>官网账号</td><td>邮箱、密码（加盐后用 PBKDF2 算的哈希，看不到原密码）、注册和最近登录时间、绑定了哪几台路由器、试用领取记录。用来登录、拿登录码、续期。</td><td>到你注销账号为止；注销后 30 天内能恢复，之后彻底删除</td></tr>\n\t<tr><td>登录过的设备</td><td>每次登录记下：设备类型（比如「安卓手机 · Edge」，只存这几个字，不存浏览器的原始信息）、大概的城市（Cloudflare 提供；IP 另外记在下面的「登录记录」里）、登录和最近使用时间。在账号页给你看、让你退出不认识的设备；新设备登录时给你发提醒邮件。</td><td>那次登录失效时删除（30 天、退出、改密码、被你在账号页退出）</td></tr>\n\t<tr><td>路由器登记</td><td>专属网址编号、路由器名字（主机名）和型号、开通和最近上线时间、到期时间、用的哪个邀请码。用来开通网址、判断是否在线、到期提醒。</td><td>卸载时马上删除；90 天没上线放进回收站，30 天后彻底删除</td></tr>\n\t<tr><td>运行状态</td><td>路由器每分钟报一次：宽带、外网、DNS、隧道、面板、代理插件是不是正常。用来判断断电断网、推送提醒。<b>不含上网记录、访问了哪些网站。</b></td><td>只留最近 300 条状态变化；删除路由器时一起删</td></tr>\n\t<tr><td>推送</td><td>你在手机上打开推送时的订阅地址；开了微信推送的，还有 PushPlus 的 token。</td><td>到你关掉推送或删除路由器为止</td></tr>\n\t<tr><td>云端备份</td><td>路由器全部设置的整包（包括 Wi-Fi 密码、宽带账号、面板登录密钥）。<b>开启加密后</b>（v2.0.8 起）只存路由器加密过的密文，托管服务看不到内容；<b>没开启加密的原样存着</b>。</td><td>最多留最近 10 份；你在面板里删、关掉云端备份或卸载时删除</td></tr>\n\t<tr><td>问题反馈、报告</td><td>你写的内容、联系方式、截图；面板里发的还有你选择附上的路由器信息（面板版本、代理插件等，不含密钥和网址）和绑定账号的邮箱。<b>安装失败时</b>，只有你在终端里输入 y 同意才会发：面板版本、失败的步骤和错误、系统版本和型号、内核、剩余空间和内存、装了哪些代理插件，以及这次安装在屏幕上显示的全过程（邀请码、令牌、域名会先在路由器上遮住）。用来回复和修问题。</td><td>只留最近 300 条，处理后可以删除</td></tr>\n\t<tr><td>续期申请</td><td>申请表里填的内容和账号邮箱。用来审核续期。</td><td>审核记录留在管理后台</td></tr>\n\t<tr><td>登录记录</td><td>4.0 起，官网账号每次登录（成功或失败）、注册、找回密码，以及管理后台的登录和输错密钥，都记下：<b>IP 地址</b>、大概的城市、设备类型（比如「安卓手机 · Edge」）、时间和结果。用来发现有人在猜密码、异地登录这类安全问题。只有管理员能看到。</td><td>90 天后自动删除</td></tr>\n\t<tr><td>官网访问统计</td><td>4.0 起，官网各页（首页、账号页、查进度、本页等）每天被打开多少次、来自哪个国家或地区；为了算「多少个不同的访客」和防刷量，记下访客的 <b>IP 地址</b>和这一天打开了几次。不记你看了哪些内容、没有 Cookie、不跟踪你在别的网站的行为。管理后台不算在内。</td><td>IP 30 天后自动删除；每天的次数留 180 天</td></tr>\n\t<tr><td>实时对话</td><td>4.0 起，你在面板里「实时联系开发者」发的文字和图片、开发者的回复；附带路由器名字、型号、面板版本、发消息的手机或电脑类型、路由器大概在哪个城市。自建版第一次发消息时，官网给这台路由器一个匿名编号（只存钥匙的哈希）。</td><td>每个对话只留最近 500 条；开发者可以删除整个对话</td></tr>\n\t<tr><td>邮件和出错记录</td><td>托管服务发出的邮件（发给谁、标题、成没成功，不存正文），官网接口出错时的地址和原因。5.0 起，面板的程序出错时，路由器会把<b>错误信息本身</b>和手机类型（比如「安卓 · Edge」）、屏幕大小、在哪一页一起发过来（网址里的参数会先去掉，不带任何设置、密钥和上网内容），用来发现只在某些手机上出现的问题。</td><td>各只留最近 300 条</td></tr>\n\t<tr><td>公告统计</td><td>5.0 起，路由器取公告时带一个<b>随机生成的匿名编号</b>（存在路由器上，跟账号、密钥、IP 都没关系），用来统计每条公告有多少台路由器收到、多少台在面板里点开看了。</td><td>跟着公告一起删除</td></tr>\n\t<tr><td>数据备份</td><td>5.0 起，上面这些托管服务的数据每天自动复制一份到 Cloudflare 上另一个独立的存储，防止误删和出错后找不回来。</td><td>只留最近 7 天</td></tr>\n\t<tr><td>操作记录</td><td>管理员和系统做了什么（开通、续期、删除等），带路由器编号或账号邮箱。用来查问题。</td><td>只留最近 500 条</td></tr>\n\t<tr><td>限次记录</td><td>为了防暴力破解和刷量，按 IP 或邮箱记次数。</td><td>两天内自动删除</td></tr>\n</table></div>\n\n<h2>不收集什么</h2>\n<ul>\n\t<li>上网记录、访问的网站、流量统计：只在你的路由器上，不上传（流量统计也不在云端备份里）。</li>\n\t<li>面板里的操作内容：面板的请求经 Cloudflare 隧道直接到你的路由器，托管服务的程序不经手、不记录。</li>\n\t<li>没有广告和跟踪代码。官网（不包括面板）用了 Cloudflare 网页统计，只统计各页面的访问量和从哪个网站点进来：不用 Cookie，不记录 IP，也认不出是谁。官网自己的访问统计见上表（IP 30 天后删）。你的面板里没有任何统计。</li>\n</ul>\n\n<h2>交给了谁</h2>\n<p>托管服务没有出售或分享你的数据。下面这些服务商会经手一部分数据，它们按自己的隐私政策处理：</p>\n<ul>\n\t<li><b>Cloudflare</b>：网站、隧道和上面所有数据的存储都在 Cloudflare 上；官网的访问量统计也是 Cloudflare 网页统计做的。在外面打开面板的流量经 Cloudflare 加密转发，Cloudflare 技术上能看到内容。数据存放的服务器<b>可能在中国大陆以外</b>。</li>\n\t<li><b>Resend</b>：发验证码邮件、给管理员的提醒邮件（会经手你的邮箱地址和邮件内容）。</li>\n\t<li><b>手机和浏览器的推送服务</b>（如 Google、Apple、Mozilla）：推送内容是加密的，推送服务看不到。</li>\n\t<li><b>PushPlus</b>：只在你开了微信推送时。推送内容（比如「新设备连上了」会带设备名、IP 和 MAC 地址）原样交给 PushPlus 发到微信。</li>\n\t<li><b>GitHub</b>：安装包和更新从 GitHub 下载，下载时 GitHub 会看到路由器的 IP。</li>\n\t<li><b>Anthropic（Claude）</b>：只在 AI 版、你把连接器加到 Claude 时。Claude 按你的对话读取和操作路由器，相关内容按 Anthropic 的政策处理。</li>\n</ul>\n\n<h2>你能做什么</h2>\n<ul>\n\t<li><b>看</b>：<a href=\"/app\">账号页</a>能看到绑定的路由器和到期时间；面板「云端备份」页能看到每一份备份。</li>\n\t<li><b>导出</b>：云端备份可以在面板里下载到手机；其他数据要导出，用<a href=\"/security#report\">报告表单</a>告诉我们。</li>\n\t<li><b>删除</b>：<a href=\"/app\">账号页</a>可以注销账号；面板里可以删备份、关推送、关云端备份；路由器上运行卸载脚本，这台路由器在云端的数据马上删除。其他的用<a href=\"/security#report\">报告表单</a>要求删除。</li>\n</ul>\n\n<h2>家长控制</h2>\n<p>面板的「暂停上网」可能用在孩子的设备上。要不要用、对哪台设备用，由家长决定和设置；托管服务不收集被暂停设备的上网内容。</p>\n\n<h2>变更和联系</h2>\n<p>这份政策有变化时会更新本页和上面的日期。有问题请用<a href=\"/security#report\">报告表单</a>（选「隐私和数据」）。</p>\n\n<footer><a href=\"/\">首页</a> · <a href=\"/notice\">用户须知</a> · <a href=\"/terms\">用户使用协议</a> · <a href=\"/security\">安全说明</a> · <a href=\"/app\">账号</a> · <a href=\"https://github.com/wznwzn123/openwrt-claude-panel\" rel=\"noopener\">GitHub</a></footer>\n</div></body></html>\n";
export const SECURITY = "<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\">\n<link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect width='100' height='100' rx='22.5' fill='%23101C40'/><path d='M41.91 24.45A29 29 0 1 0 75.55 58.09A24 24 0 0 1 41.91 24.45Z' fill='%23F4F1EA'/><path d='M62.6 21.4A17 17 0 0 1 78.6 37.4' stroke='%23FFB547' stroke-width='4' stroke-linecap='round' fill='none'/><circle cx='63' cy='37' r='7' fill='%23FFB547'/></svg>\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,minimum-scale=1,viewport-fit=cover\">\n<title>安全说明 · 路由器面板</title>\n<meta name=\"description\" content=\"路由器面板做了哪些安全措施、还有哪些风险没覆盖、出了问题怎么办、怎么报告安全问题。\">\n<style>:root{--bg:#eef1f8;--card:rgba(255,255,255,.66);--card2:rgba(255,255,255,.55);--text:#0b0b0f;--muted:#6e6e73;--line:rgba(60,60,67,.14);--fill:rgba(118,118,128,.14);--brand:#007aff;--ok:#34c759;--danger:#ff3b30;--warn:#ff9500;--shadow:inset 0 0 0 .5px rgba(255,255,255,.65),0 8px 28px rgba(31,38,80,.08);color-scheme:light}\n@media(prefers-color-scheme:dark){:root{--bg:#0b1024;--card:rgba(28,28,32,.58);--card2:rgba(72,72,80,.36);--text:#f5f5f7;--muted:#98989f;--line:rgba(255,255,255,.1);--fill:rgba(118,118,128,.26);--brand:#0a84ff;--ok:#30d158;--danger:#ff453a;--shadow:inset 0 0 0 .5px rgba(255,255,255,.09),0 8px 28px rgba(0,0,0,.28);color-scheme:dark}}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;min-height:100vh;color:var(--text);font:15px/1.55 -apple-system,BlinkMacSystemFont,\"SF Pro Text\",\"PingFang SC\",\"Noto Sans SC\",\"Microsoft YaHei\",system-ui,sans-serif;-webkit-font-smoothing:antialiased;background:var(--bg)}\nbody::before{content:\"\";position:fixed;inset:-40px;z-index:-1;filter:blur(20px);background:radial-gradient(60% 50% at 12% 8%,#c3d2ff 0,transparent 70%),radial-gradient(55% 45% at 92% 18%,#f6cdf0 0,transparent 70%),radial-gradient(70% 55% at 30% 95%,#b8ecff 0,transparent 70%),radial-gradient(50% 40% at 85% 80%,#d9ccff 0,transparent 70%),var(--bg)}\n@media(prefers-color-scheme:dark){body::before{background:radial-gradient(55% 45% at 15% 10%,#3a2c8f 0,transparent 70%),radial-gradient(50% 45% at 90% 25%,#13527a 0,transparent 70%),radial-gradient(70% 55% at 40% 100%,#4b1e6b 0,transparent 70%),#0b1024}}\na{color:var(--brand);text-decoration:none;font-weight:600}\nbutton,input,select{font:inherit;color:inherit}\nbutton{border:0;cursor:pointer}\n.wrap{max-width:960px;margin:auto;padding:16px 16px 60px}\n.top{position:sticky;top:8px;z-index:10;display:flex;align-items:center;justify-content:space-between;gap:10px;margin:8px 0 18px;padding:10px 14px;border-radius:22px;background:color-mix(in srgb,var(--bg) 82%,transparent);-webkit-backdrop-filter:saturate(180%) blur(24px);backdrop-filter:saturate(180%) blur(24px);box-shadow:var(--shadow)}\n.logo{display:flex;align-items:center;gap:10px;font-weight:700;font-size:17px;color:var(--text)}\n.logo i{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;background:#101C40;color:#fff;font-style:normal;font-size:18px;overflow:hidden;box-shadow:inset 0 0 0 .5px rgba(255,255,255,.18)}.logo i svg{width:100%;height:100%;display:block}\n.card{background:var(--card);border-radius:22px;padding:18px;box-shadow:var(--shadow);min-width:0}\n.muted{color:var(--muted)}\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:10px 18px;border-radius:99px;background:var(--fill);color:var(--text);font-weight:650;font-size:15px;transition:transform .15s,opacity .2s;white-space:nowrap}\n.btn:active{transform:scale(.96)}.btn:disabled{opacity:.5}\n.btn.primary{background:var(--brand);color:#fff}.btn.danger{color:var(--danger)}.btn.sm{padding:7px 13px;font-size:13.5px}\n.input{width:100%;padding:12px 14px;border-radius:14px;border:0;background:var(--fill);outline:0;font-size:16px;min-width:0}\n.input:focus{box-shadow:0 0 0 3px rgba(0,122,255,.25)}\n.input::placeholder{color:var(--muted);opacity:.7}\nlabel.f{display:block;margin:12px 0 6px;font-size:13px;font-weight:600;color:var(--muted)}\n.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}\n.notice{padding:11px 13px;border-radius:14px;background:var(--fill);font-size:13.5px;color:var(--muted);line-height:1.6}\n.err{color:var(--danger);font-size:13.5px;min-height:20px;margin-top:8px}\n.toast{position:fixed;left:0;right:0;top:16px;margin:auto;width:max-content;max-width:calc(100% - 32px);padding:10px 16px;border-radius:18px;background:var(--card);-webkit-backdrop-filter:blur(24px);backdrop-filter:blur(24px);box-shadow:var(--shadow),0 10px 30px rgba(0,0,0,.15);font-weight:600;font-size:14px;z-index:99;transition:opacity .3s,transform .3s}\n.toast.hide{opacity:0;transform:translateY(-10px);pointer-events:none}\n.hidden{display:none!important}\n.dot{width:9px;height:9px;border-radius:50%;background:#aaa;display:inline-block;flex:none}.dot.on{background:var(--ok)}.dot.off{background:var(--danger)}\nh1,h2,h3{letter-spacing:-.02em;margin:0}\n\n/* 顶栏上面那一条：往上滚的内容在这里淡出，不会从顶栏上方露出来 */\nbody::after{content:\"\";position:fixed;left:0;right:0;top:0;height:calc(env(safe-area-inset-top) + 34px);z-index:9;pointer-events:none;background:linear-gradient(var(--bg) 45%,color-mix(in srgb,var(--bg) 0%,transparent))}\nh2,.sech{scroll-margin-top:90px}\n/* 反馈进度条：反馈成功 → 开发人员已收到 → 已修复 / 无法修复（只显示这三段，补充说明写在下面） */\n.fsteps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin:6px 0 4px}\n.fsteps>div{position:relative;display:flex;flex-direction:column;align-items:center;text-align:center;min-width:0}\n.fsteps>div+div::before{content:'';position:absolute;top:10px;right:calc(50% + 15px);width:calc(100% - 30px);height:3px;border-radius:2px;background:var(--line)}\n.fsteps>div.on::before{background:var(--ok)}.fsteps>div.bad::before{background:var(--danger)}\n.fsteps i{width:23px;height:23px;border-radius:50%;display:grid;place-items:center;font-style:normal;font-size:12px;font-weight:700;background:var(--fill);color:var(--muted)}\n.fsteps .on i{background:var(--ok);color:#fff}.fsteps .bad i{background:var(--danger);color:#fff}\n.fsteps .cur i{box-shadow:0 0 0 4px color-mix(in srgb,var(--ok) 22%,transparent)}.fsteps .bad.cur i{box-shadow:0 0 0 4px color-mix(in srgb,var(--danger) 22%,transparent)}\n.fsteps b{display:block;font-size:12.5px;font-weight:600;margin-top:7px;line-height:1.3;word-break:keep-all}\n.fsteps .off b{color:var(--muted);font-weight:500}.fsteps .bad b{color:var(--danger)}\n\n.doc h1{font-size:28px;margin:18px 0 4px}.doc .sub{color:var(--muted);font-size:13.5px;margin:0 0 18px}\n.doc h2{font-size:19px;margin:28px 0 10px}.doc p,.doc li{font-size:14.5px;line-height:1.8}.doc ul,.doc ol{padding-left:20px;margin:6px 0}\ntextarea.input{min-height:130px;resize:vertical;font:inherit;line-height:1.6}\n.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}\nfooter{margin-top:40px;text-align:center;color:var(--muted);font-size:13px}\n</style></head><body><div class=\"wrap doc\">\n<div class=\"top\"><a class=\"logo\" href=\"/\"><i><svg viewBox=\"0 0 100 100\" fill=\"none\" aria-hidden=\"true\"><path d=\"M41.91 24.45A29 29 0 1 0 75.55 58.09A24 24 0 0 1 41.91 24.45Z\" fill=\"#F4F1EA\"/><path d=\"M62.6 21.4A17 17 0 0 1 78.6 37.4\" stroke=\"#FFB547\" stroke-width=\"4\" stroke-linecap=\"round\" fill=\"none\"/><circle cx=\"63\" cy=\"37\" r=\"7\" fill=\"#FFB547\"/></svg></i>路由器面板</a><div class=\"row\"><a class=\"btn sm\" href=\"/privacy\">隐私政策</a><a class=\"btn sm primary\" href=\"/app\">登录</a></div></div>\n\n<h1>安全说明</h1>\n<p class=\"sub\">我们做了下面这些措施，发现问题会持续修；没覆盖的风险也写在这里。支持哪些系统、测过哪些、已知问题见<a href=\"https://github.com/wznwzn123/openwrt-claude-panel/blob/main/docs/compatibility.md\" rel=\"noopener\">兼容性和已知问题</a>。最后更新：2026 年 11 月 7 日</p>\n\n<h2>做了哪些措施</h2>\n<div class=\"card\"><ul style=\"margin:0\">\n\t<li><b>登录密钥</b>在路由器上生成，保存在路由器和你自己的手机上；官网账号里没有密钥。</li>\n\t<li><b>新手机要登录码</b>（托管版）：只有绑定了这台路由器的账号能拿，10 分钟有效、用一次作废；输错 10 次锁 10 分钟。</li>\n\t<li><b>官网登录限次</b>：密码输错、验证码、注册都有次数限制。</li>\n\t<li><b>登录过的设备</b>：<a href=\"/app\">账号页</a>能看到哪些设备登录着你的账号，可以单独退出或一键退出其他所有设备；有新设备登录会发邮件提醒；改密码时其他设备自动退出。</li>\n\t<li><b>随时换钥匙</b>：面板「系统操作」里能换登录密钥，旧地址马上作废；Claude 连接器是单独一把钥匙，可以单独换。</li>\n\t<li><b>安装包和更新</b>：一键更新下载后先核对 SHA256，不对就不装。每次发布都附一份依赖清单（SBOM）；代码每次更新都自动扫一遍有没有泄露的密钥、用到的组件有没有已知漏洞。</li>\n\t<li><b>卸载干净</b>：卸载后逐项检查有没有留下东西，结果存一份记录。</li>\n\t<li><b>云端备份可以加密</b>（v2.0.8 起）：开启后在路由器上加密再上传，密钥只在路由器上；下载、还原时先校验，被改过的不会使用。</li>\n\t<li><b>官网页面</b>：不能被别的网站嵌入，不加载外部脚本；没有广告、统计、跟踪代码。</li>\n</ul></div>\n\n<h2>没覆盖的风险</h2>\n<div class=\"card\"><ol style=\"margin:0\">\n\t<li><b>更新来自 GitHub</b>：一键更新装的是我们在 GitHub 发布的安装包，目前只核对文件完整，没有签名。发布账号如果被盗，可能推送有问题的更新。</li>\n\t<li><b>Cloudflare 能看到流量</b>：在外面打开面板时，流量经 Cloudflare 加密转发，Cloudflare 那一层能看到内容。</li>\n\t<li><b>登录地址和官网账号同时泄露</b>：别人就能拿登录码打开面板。面板能执行命令，打开面板就等于拿到路由器的最高权限，所以登录地址请当密码保管，不要截图分享。</li>\n\t<li><b>没开启加密的云端备份</b>：里面的 Wi-Fi 密码、登录密钥等原样存在云端。</li>\n\t<li><b>推送内容</b>：微信推送（PushPlus）是明文；「新设备提醒」带设备名、IP 和 MAC 地址。</li>\n\t<li><b>不在这个项目范围内的</b>：OpenWrt 系统本身、其他插件、路由器后台（LuCI）和 SSH 的安全。面板不会替你打开这些的公网访问。</li>\n</ol></div>\n\n<h2>觉得被别人动过了，怎么办</h2>\n<div class=\"card\"><ol style=\"margin:0\">\n\t<li>面板「系统操作 → 换登录密钥」，所有旧地址马上作废，再用自己的手机重新添加。</li>\n\t<li>用 AI 版的：同一页换「Claude 连接器地址」。</li>\n\t<li>官网<a href=\"/app\">账号页</a>「登录过的设备」里把不认识的退出（或者一键退出其他所有设备），再改密码；不放心就注销账号重新注册。</li>\n\t<li>改路由器的 root 密码和 Wi-Fi 密码（路由器后台「系统 → 管理权」「网络 → 无线」）。</li>\n\t<li>面板「云端备份」里删掉不放心的备份。</li>\n\t<li>还是不放心：在路由器上运行卸载命令（<code>cmcp-uninstall</code>，5.0 以前的版本在安装包目录里运行 <code>sh uninstall.sh</code>），专属网址和云端数据马上删除。</li>\n</ol></div>\n\n<h2 id=\"report\">报告问题</h2>\n<div class=\"card\">\n\t<p style=\"margin:0 0 10px\">发现安全漏洞、想查询或删除自己的数据、发现有人滥用这个服务，都可以在这里告诉我们。不用登录。<b>请不要写密码、登录地址这些密钥</b>。这个项目是一个人维护的，收到后会尽快回复；确认的问题修好后会写在更新说明里。</p>\n\t<form id=\"rpForm\" autocomplete=\"off\" novalidate>\n\t\t<label class=\"f\">类型<select class=\"input\" name=\"kind\">\n\t\t\t<option value=\"security\">安全问题（漏洞、可能被入侵）</option>\n\t\t\t<option value=\"privacy\">隐私和数据（查询、导出、删除）</option>\n\t\t\t<option value=\"abuse\">滥用举报</option>\n\t\t\t<option value=\"other\">其他</option>\n\t\t</select></label>\n\t\t<label class=\"f\">内容<textarea class=\"input\" name=\"text\" maxlength=\"4000\" placeholder=\"发生了什么、在哪个页面或功能、怎么能重现……\" required></textarea></label>\n\t\t<label class=\"f\">邮箱（建议填，处理进度会发邮件告诉你）<input class=\"input\" name=\"email\" type=\"email\" maxlength=\"120\" placeholder=\"you@example.com\" autocomplete=\"email\" inputmode=\"email\"></label>\n\t\t<p class=\"muted hidden\" id=\"rpMe\" style=\"margin:-4px 0 10px;font-size:12.5px\"></p>\n\t\t<label class=\"f\">其他联系方式（可以不填）<input class=\"input\" name=\"contact\" maxlength=\"120\" placeholder=\"微信或 QQ\"></label>\n\t\t<div class=\"hp\" aria-hidden=\"true\"><label>网址<input name=\"website\" tabindex=\"-1\" autocomplete=\"off\"></label></div>\n\t\t<button class=\"btn primary\" type=\"submit\" id=\"rpGo\" style=\"width:100%;margin-top:6px\">提交</button>\n\t\t<p class=\"err hidden\" id=\"rpErr\" style=\"margin:8px 0 0\"></p>\n\t</form>\n\t<div class=\"hidden\" id=\"rpOk\"><div class=\"notice\" style=\"margin:0\">已经收到，谢谢！<span id=\"rpCode\"></span></div></div>\n\t<p style=\"margin:12px 0 0;font-size:13.5px;color:var(--muted)\">以前报告过？<a href=\"/r\">输入编号查处理进度</a></p>\n</div>\n\n<footer><a href=\"/\">首页</a> · <a href=\"/notice\">用户须知</a> · <a href=\"/terms\">用户使用协议</a> · <a href=\"/privacy\">隐私政策</a> · <a href=\"/app\">账号</a> · <a href=\"https://github.com/wznwzn123/openwrt-claude-panel\" rel=\"noopener\">GitHub</a></footer>\n</div>\n<script>\nconst F = document.getElementById('rpForm'), go = document.getElementById('rpGo'), er = document.getElementById('rpErr');\nF.addEventListener('submit', async (e) => {\n\te.preventDefault();\n\tconst d = Object.fromEntries(new FormData(F));\n\ter.classList.add('hidden');\n\tif ((d.text || '').trim().length < 10) { er.textContent = '多写几句，说清楚是什么问题（至少 10 个字）'; er.classList.remove('hidden'); return; }\n\td.email = (d.email || '').trim();\n\tif (d.email && !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test(d.email)) { er.textContent = '邮箱格式不对'; er.classList.remove('hidden'); return; }\n\tgo.disabled = true; go.textContent = '提交中…';\n\ttry {\n\t\tconst r = await fetch('/api/report', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(d) });\n\t\tconst j = await r.json().catch(() => ({}));\n\t\tif (!r.ok) throw new Error(j.error || '提交失败（' + r.status + '）');\n\t\tF.classList.add('hidden'); document.getElementById('rpOk').classList.remove('hidden');\n\t\t// 有编号：显示编号和进度页，不用留联系方式也能看到回复\n\t\tif (/^[a-z2-9]{8}$/.test(j.code || '')) { const c = j.code.toUpperCase(); document.getElementById('rpCode').innerHTML = `受理编号 <b>${c}</b>，处理进度和回复在 <a href=\"/r/${c}\">这个网址</a> 能看到，建议收藏。` + (j.mailed ? '确认邮件已经发到你的邮箱，有进展也会发邮件告诉你。' : ''); }\n\t\telse document.getElementById('rpCode').textContent = '留了联系方式的会尽快回复你。';\n\t} catch (x) { er.textContent = x.message; er.classList.remove('hidden'); go.disabled = false; go.textContent = '提交'; }\n});\n// 登录了官网账号：邮箱自动填账号邮箱（可以改），这条报告也会出现在账号页「我的反馈」里\nfetch('/api/account/me').then((r) => (r.ok ? r.json() : null)).then((j) => {\n\tif (!j || !j.email) return;\n\tif (!F.email.value) F.email.value = j.email;\n\tconst m = document.getElementById('rpMe'); m.textContent = '你已经登录，邮箱用的是账号邮箱；这条报告也会显示在账号页「我的反馈」里'; m.classList.remove('hidden');\n}).catch(() => {});\n</script>\n</body></html>\n";
export const REPLY = "<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\">\n<link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect width='100' height='100' rx='22.5' fill='%23101C40'/><path d='M41.91 24.45A29 29 0 1 0 75.55 58.09A24 24 0 0 1 41.91 24.45Z' fill='%23F4F1EA'/><path d='M62.6 21.4A17 17 0 0 1 78.6 37.4' stroke='%23FFB547' stroke-width='4' stroke-linecap='round' fill='none'/><circle cx='63' cy='37' r='7' fill='%23FFB547'/></svg>\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,minimum-scale=1,viewport-fit=cover\">\n<title>处理进度 · 路由器面板</title>\n<meta name=\"robots\" content=\"noindex\">\n<style>:root{--bg:#eef1f8;--card:rgba(255,255,255,.66);--card2:rgba(255,255,255,.55);--text:#0b0b0f;--muted:#6e6e73;--line:rgba(60,60,67,.14);--fill:rgba(118,118,128,.14);--brand:#007aff;--ok:#34c759;--danger:#ff3b30;--warn:#ff9500;--shadow:inset 0 0 0 .5px rgba(255,255,255,.65),0 8px 28px rgba(31,38,80,.08);color-scheme:light}\n@media(prefers-color-scheme:dark){:root{--bg:#0b1024;--card:rgba(28,28,32,.58);--card2:rgba(72,72,80,.36);--text:#f5f5f7;--muted:#98989f;--line:rgba(255,255,255,.1);--fill:rgba(118,118,128,.26);--brand:#0a84ff;--ok:#30d158;--danger:#ff453a;--shadow:inset 0 0 0 .5px rgba(255,255,255,.09),0 8px 28px rgba(0,0,0,.28);color-scheme:dark}}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;min-height:100vh;color:var(--text);font:15px/1.55 -apple-system,BlinkMacSystemFont,\"SF Pro Text\",\"PingFang SC\",\"Noto Sans SC\",\"Microsoft YaHei\",system-ui,sans-serif;-webkit-font-smoothing:antialiased;background:var(--bg)}\nbody::before{content:\"\";position:fixed;inset:-40px;z-index:-1;filter:blur(20px);background:radial-gradient(60% 50% at 12% 8%,#c3d2ff 0,transparent 70%),radial-gradient(55% 45% at 92% 18%,#f6cdf0 0,transparent 70%),radial-gradient(70% 55% at 30% 95%,#b8ecff 0,transparent 70%),radial-gradient(50% 40% at 85% 80%,#d9ccff 0,transparent 70%),var(--bg)}\n@media(prefers-color-scheme:dark){body::before{background:radial-gradient(55% 45% at 15% 10%,#3a2c8f 0,transparent 70%),radial-gradient(50% 45% at 90% 25%,#13527a 0,transparent 70%),radial-gradient(70% 55% at 40% 100%,#4b1e6b 0,transparent 70%),#0b1024}}\na{color:var(--brand);text-decoration:none;font-weight:600}\nbutton,input,select{font:inherit;color:inherit}\nbutton{border:0;cursor:pointer}\n.wrap{max-width:960px;margin:auto;padding:16px 16px 60px}\n.top{position:sticky;top:8px;z-index:10;display:flex;align-items:center;justify-content:space-between;gap:10px;margin:8px 0 18px;padding:10px 14px;border-radius:22px;background:color-mix(in srgb,var(--bg) 82%,transparent);-webkit-backdrop-filter:saturate(180%) blur(24px);backdrop-filter:saturate(180%) blur(24px);box-shadow:var(--shadow)}\n.logo{display:flex;align-items:center;gap:10px;font-weight:700;font-size:17px;color:var(--text)}\n.logo i{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;background:#101C40;color:#fff;font-style:normal;font-size:18px;overflow:hidden;box-shadow:inset 0 0 0 .5px rgba(255,255,255,.18)}.logo i svg{width:100%;height:100%;display:block}\n.card{background:var(--card);border-radius:22px;padding:18px;box-shadow:var(--shadow);min-width:0}\n.muted{color:var(--muted)}\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:10px 18px;border-radius:99px;background:var(--fill);color:var(--text);font-weight:650;font-size:15px;transition:transform .15s,opacity .2s;white-space:nowrap}\n.btn:active{transform:scale(.96)}.btn:disabled{opacity:.5}\n.btn.primary{background:var(--brand);color:#fff}.btn.danger{color:var(--danger)}.btn.sm{padding:7px 13px;font-size:13.5px}\n.input{width:100%;padding:12px 14px;border-radius:14px;border:0;background:var(--fill);outline:0;font-size:16px;min-width:0}\n.input:focus{box-shadow:0 0 0 3px rgba(0,122,255,.25)}\n.input::placeholder{color:var(--muted);opacity:.7}\nlabel.f{display:block;margin:12px 0 6px;font-size:13px;font-weight:600;color:var(--muted)}\n.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}\n.notice{padding:11px 13px;border-radius:14px;background:var(--fill);font-size:13.5px;color:var(--muted);line-height:1.6}\n.err{color:var(--danger);font-size:13.5px;min-height:20px;margin-top:8px}\n.toast{position:fixed;left:0;right:0;top:16px;margin:auto;width:max-content;max-width:calc(100% - 32px);padding:10px 16px;border-radius:18px;background:var(--card);-webkit-backdrop-filter:blur(24px);backdrop-filter:blur(24px);box-shadow:var(--shadow),0 10px 30px rgba(0,0,0,.15);font-weight:600;font-size:14px;z-index:99;transition:opacity .3s,transform .3s}\n.toast.hide{opacity:0;transform:translateY(-10px);pointer-events:none}\n.hidden{display:none!important}\n.dot{width:9px;height:9px;border-radius:50%;background:#aaa;display:inline-block;flex:none}.dot.on{background:var(--ok)}.dot.off{background:var(--danger)}\nh1,h2,h3{letter-spacing:-.02em;margin:0}\n\n/* 顶栏上面那一条：往上滚的内容在这里淡出，不会从顶栏上方露出来 */\nbody::after{content:\"\";position:fixed;left:0;right:0;top:0;height:calc(env(safe-area-inset-top) + 34px);z-index:9;pointer-events:none;background:linear-gradient(var(--bg) 45%,color-mix(in srgb,var(--bg) 0%,transparent))}\nh2,.sech{scroll-margin-top:90px}\n/* 反馈进度条：反馈成功 → 开发人员已收到 → 已修复 / 无法修复（只显示这三段，补充说明写在下面） */\n.fsteps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin:6px 0 4px}\n.fsteps>div{position:relative;display:flex;flex-direction:column;align-items:center;text-align:center;min-width:0}\n.fsteps>div+div::before{content:'';position:absolute;top:10px;right:calc(50% + 15px);width:calc(100% - 30px);height:3px;border-radius:2px;background:var(--line)}\n.fsteps>div.on::before{background:var(--ok)}.fsteps>div.bad::before{background:var(--danger)}\n.fsteps i{width:23px;height:23px;border-radius:50%;display:grid;place-items:center;font-style:normal;font-size:12px;font-weight:700;background:var(--fill);color:var(--muted)}\n.fsteps .on i{background:var(--ok);color:#fff}.fsteps .bad i{background:var(--danger);color:#fff}\n.fsteps .cur i{box-shadow:0 0 0 4px color-mix(in srgb,var(--ok) 22%,transparent)}.fsteps .bad.cur i{box-shadow:0 0 0 4px color-mix(in srgb,var(--danger) 22%,transparent)}\n.fsteps b{display:block;font-size:12.5px;font-weight:600;margin-top:7px;line-height:1.3;word-break:keep-all}\n.fsteps .off b{color:var(--muted);font-weight:500}.fsteps .bad b{color:var(--danger)}\n\n.doc h1{font-size:26px;margin:18px 0 4px}.doc .sub{color:var(--muted);font-size:13.5px;margin:0 0 18px}\n.st{display:flex;align-items:center;gap:12px;margin:0 0 4px}\n.st i{flex:none;width:44px;height:44px;border-radius:14px;display:grid;place-items:center;font-style:normal;font-size:22px;color:#fff}\n.st b{font-size:19px}.st span{display:block;color:var(--muted);font-size:13px;margin-top:2px}\n.ok .st i{background:linear-gradient(135deg,#3fd38a,#18a874)}.wait .st i{background:linear-gradient(135deg,#ffb36b,#ff8a3d)}.bad .st i{background:linear-gradient(135deg,#ff7a6b,#e5484d)}\n.bar{margin-top:16px;padding:14px 4px 12px;border-radius:14px;background:var(--fill)}\n.lg h2{font-size:16px;margin:0 0 4px}\n.ev{position:relative;padding:12px 0 12px 20px;border-bottom:.5px solid var(--line)}.ev:last-child{border-bottom:0;padding-bottom:2px}\n.ev::before{content:'';position:absolute;left:2px;top:19px;width:8px;height:8px;border-radius:50%;background:var(--muted)}\n.ev.fixed::before{background:var(--ok)}.ev.nofix::before{background:var(--danger)}.ev.note::before,.ev.ack::before{background:var(--brand)}\n.ev b{font-size:14.5px}.ev time{display:block;color:var(--muted);font-size:12.5px;margin-top:1px}\n.ev p{margin:8px 0 0;padding:11px 13px;border-radius:12px;background:var(--fill);font-size:15px;line-height:1.75;white-space:pre-wrap;word-break:break-word}\n.q{display:flex;gap:10px;margin-top:12px}.q input{flex:1;min-width:0;text-transform:uppercase;letter-spacing:.12em;font-size:17px}.q button{flex:none}\n.kv{display:flex;justify-content:space-between;font-size:14px;padding:8px 0;border-bottom:.5px solid var(--line)}.kv:last-child{border-bottom:0}.kv span{color:var(--muted)}\nfooter{margin-top:40px;text-align:center;color:var(--muted);font-size:13px}\n</style></head><body><div class=\"wrap doc\">\n<div class=\"top\"><a class=\"logo\" href=\"/\"><i><svg viewBox=\"0 0 100 100\" fill=\"none\" aria-hidden=\"true\"><path d=\"M41.91 24.45A29 29 0 1 0 75.55 58.09A24 24 0 0 1 41.91 24.45Z\" fill=\"#F4F1EA\"/><path d=\"M62.6 21.4A17 17 0 0 1 78.6 37.4\" stroke=\"#FFB547\" stroke-width=\"4\" stroke-linecap=\"round\" fill=\"none\"/><circle cx=\"63\" cy=\"37\" r=\"7\" fill=\"#FFB547\"/></svg></i>路由器面板</a><div class=\"row\"><a class=\"btn sm primary\" href=\"/app\">登录</a></div></div>\n<h1>处理进度</h1>\n<p class=\"sub\">你上报的问题，开发者处理到哪一步了、说了什么，都在这里。不用登录，有编号就能查。</p>\n<div class=\"card\" id=\"box\"><p style=\"margin:0;color:var(--muted)\">正在查……</p></div>\n<form class=\"card\" id=\"ask\" hidden style=\"margin-top:12px\" autocomplete=\"off\">\n\t<b style=\"font-size:16px\">输入编号查进度</b>\n\t<p style=\"margin:6px 0 0;color:var(--muted);font-size:13.5px;line-height:1.6\">编号是 8 位字母和数字，上报成功时会显示。终端安装失败上报的，在路由器上运行 <code style=\"white-space:nowrap\">cat /etc/cmcp-report</code> 也能看到。</p>\n\t<div class=\"q\"><input class=\"input\" id=\"qc\" maxlength=\"20\" placeholder=\"比如 K7F2Q9AB\" autocapitalize=\"characters\" spellcheck=\"false\" inputmode=\"latin\"><button class=\"btn primary\" type=\"submit\">查询</button></div>\n\t<p class=\"err\" id=\"qe\" hidden style=\"margin:8px 0 0\"></p>\n</form>\n<div class=\"card lg\" id=\"log\" hidden style=\"margin-top:12px\"><h2>完整记录</h2><div id=\"evs\"></div></div>\n<div class=\"card\" id=\"more\" hidden style=\"margin-top:12px\">\n\t<div class=\"kv\" style=\"align-items:center\"><span>编号</span><span style=\"display:flex;align-items:center;gap:10px;color:inherit\"><b id=\"code\" style=\"letter-spacing:.06em\"></b><button class=\"btn sm\" id=\"cp\" type=\"button\">复制</button></span></div>\n\t<div class=\"kv\"><span>类型</span><b id=\"kind\"></b></div>\n\t<div class=\"kv\"><span>上报时间</span><b id=\"at\"></b></div>\n</div>\n<p class=\"sub\" id=\"tip\" hidden style=\"margin-top:14px\"></p>\n<footer><a href=\"/r\">查别的编号</a> · <a href=\"/\">首页</a> · <a href=\"/security\">安全说明</a> · <a href=\"/app\">账号</a></footer>\n</div>\n<script>\nconst $ = (id) => document.getElementById(id);\nconst esc = (x) => String(x ?? '').replace(/[&<>\"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' })[c]);\nconst when = (t) => new Date(t).toLocaleString('zh-CN', { hour12: false, month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' });\n// 进度条：反馈成功 → 开发人员已收到 → 已修复（没法修的，第三段变成「无法修复」）\nconst steps = (stage, nofix) => `<div class=\"fsteps\" data-stage=\"${stage}\">${['反馈成功', '开发人员已收到', '已修复'].map((x, i) => { const on = i < stage, bad = on && i === 2 && nofix;\n\treturn `<div class=\"${on ? (bad ? 'on bad' : 'on') : 'off'}${i === stage - 1 ? ' cur' : ''}\"><i>${bad ? '✕' : on ? '✓' : i + 1}</i><b>${bad ? '无法修复' : x}</b></div>`; }).join('')}</div>`;\nconst code = (location.pathname.split('/')[2] || '').toUpperCase();\n// 输入编号：0、1、O、L 这几个容易看错的字不会出现在编号里，输错了就提示\n$('ask').onsubmit = (e) => {\n\te.preventDefault(); const v = $('qc').value.trim().toUpperCase().replace(/\\s+/g, '');\n\tif (!/^[A-Z2-9]{8}$/.test(v) || /[01OL]/.test(v)) { $('qe').hidden = false; $('qe').textContent = /[01OL]/.test(v) ? '编号里没有 0、1、O、L 这几个字，看看是不是认错了' : '编号是 8 位字母和数字'; return; }\n\tlocation.href = '/r/' + v;\n};\nconst ask = (msg) => { $('box').hidden = !msg; if (msg) $('box').innerHTML = `<p style=\"margin:0\">${esc(msg)}</p>`; $('ask').hidden = false; if (!msg) $('ask').style.marginTop = '0'; };\nif (!/^[A-Z2-9]{8}$/.test(code)) ask('');\nelse fetch('/api/fb/' + encodeURIComponent(code)).then((r) => r.json()).then((d) => {\n\tif (!d.ok) { ask(d.error || '没查到'); $('qc').value = code; return; }\n\tconst state = d.state || (d.done ? 'fixed' : 'open'), stage = d.stage || (d.done ? 3 : 1);\n\tconst head = state === 'fixed' ? ['ok', '✓', '已经修复了', '修复时间：' + when(d.doneAt)]\n\t\t: state === 'nofix' ? ['bad', '✕', '暂时没法修复', '原因写在下面的记录里']\n\t\t: stage >= 2 ? ['wait', '…', '开发人员已收到，正在处理', '有进展会更新在这里'] : ['wait', '…', '已经提交，等开发人员查看', '有进展会更新在这里'];\n\t$('box').className = 'card ' + head[0];\n\t// 进度条只显示三段；补充说明这些都写在下面的「完整记录」里\n\t$('box').innerHTML = `<div class=\"st\"><i>${head[1]}</i><div><b>${head[2]}</b><span>${esc(head[3])}</span></div></div>\n\t\t<div class=\"bar\">${steps(stage, state === 'nofix')}</div>`;\n\t// 完整记录：新的在前；最下面是「反馈成功」\n\tconst NAME = { fixed: '已修复', nofix: '无法修复', open: '重新打开，继续处理', note: '补充说明' };\n\tconst evs = (d.history || (d.reply ? [{ at: d.replyAt, st: state, note: d.reply }] : [])).map((x) => ({ ...x, n: NAME[x.st] || '更新' }));\n\tif (d.ackAt) evs.push({ at: d.ackAt, st: 'ack', n: '开发人员已收到' });\n\tevs.sort((a, b) => b.at - a.at); evs.push({ at: d.at, st: 'sent', n: '反馈成功' });\n\t$('evs').innerHTML = evs.map((x) => `<div class=\"ev ${x.st}\"><b>${esc(x.n)}</b><time>${when(x.at)}</time>${x.note ? `<p>${esc(x.note)}</p>` : ''}</div>`).join('');\n\t$('log').hidden = false;\n\t$('code').textContent = d.code; $('kind').textContent = d.kind; $('at').textContent = when(d.at); $('more').hidden = false;\n\tif (d.kind === '安装失败') { $('tip').hidden = false; $('tip').textContent = state === 'nofix' ? '如果以后情况有变化（比如换了固件），可以重新运行安装命令再试，失败了再上报一次。' : d.done ? '处理好以后，在路由器上重新运行一次安装命令就行。重新运行时，终端里也会显示这里的回复。' : '重新运行安装命令时，终端最上面也会显示这里的处理结果。'; }\n\t$('cp').onclick = async () => {\n\t\ttry { await navigator.clipboard.writeText(d.code); } catch (e) { const a = document.createElement('textarea'); a.value = d.code; document.body.appendChild(a); a.select(); try { document.execCommand('copy'); } catch (x) {} a.remove(); }\n\t\t$('cp').textContent = '已复制'; setTimeout(() => { $('cp').textContent = '复制'; }, 1500);\n\t};\n}).catch(() => { $('box').innerHTML = '<p style=\"margin:0\">网络不太好，刷新一下再试。</p>'; });\n</script>\n</body></html>\n";
export const NOTICE = "<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\">\n<link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect width='100' height='100' rx='22.5' fill='%23101C40'/><path d='M41.91 24.45A29 29 0 1 0 75.55 58.09A24 24 0 0 1 41.91 24.45Z' fill='%23F4F1EA'/><path d='M62.6 21.4A17 17 0 0 1 78.6 37.4' stroke='%23FFB547' stroke-width='4' stroke-linecap='round' fill='none'/><circle cx='63' cy='37' r='7' fill='%23FFB547'/></svg>\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,minimum-scale=1,viewport-fit=cover\">\n<title>用户须知 · 路由器面板</title>\n<meta name=\"description\" content=\"路由器面板官网账号和托管服务的用户须知：账号、托管服务的开通和到期、数据、使用规范。\">\n<style>:root{--bg:#eef1f8;--card:rgba(255,255,255,.66);--card2:rgba(255,255,255,.55);--text:#0b0b0f;--muted:#6e6e73;--line:rgba(60,60,67,.14);--fill:rgba(118,118,128,.14);--brand:#007aff;--ok:#34c759;--danger:#ff3b30;--warn:#ff9500;--shadow:inset 0 0 0 .5px rgba(255,255,255,.65),0 8px 28px rgba(31,38,80,.08);color-scheme:light}\n@media(prefers-color-scheme:dark){:root{--bg:#0b1024;--card:rgba(28,28,32,.58);--card2:rgba(72,72,80,.36);--text:#f5f5f7;--muted:#98989f;--line:rgba(255,255,255,.1);--fill:rgba(118,118,128,.26);--brand:#0a84ff;--ok:#30d158;--danger:#ff453a;--shadow:inset 0 0 0 .5px rgba(255,255,255,.09),0 8px 28px rgba(0,0,0,.28);color-scheme:dark}}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;min-height:100vh;color:var(--text);font:15px/1.55 -apple-system,BlinkMacSystemFont,\"SF Pro Text\",\"PingFang SC\",\"Noto Sans SC\",\"Microsoft YaHei\",system-ui,sans-serif;-webkit-font-smoothing:antialiased;background:var(--bg)}\nbody::before{content:\"\";position:fixed;inset:-40px;z-index:-1;filter:blur(20px);background:radial-gradient(60% 50% at 12% 8%,#c3d2ff 0,transparent 70%),radial-gradient(55% 45% at 92% 18%,#f6cdf0 0,transparent 70%),radial-gradient(70% 55% at 30% 95%,#b8ecff 0,transparent 70%),radial-gradient(50% 40% at 85% 80%,#d9ccff 0,transparent 70%),var(--bg)}\n@media(prefers-color-scheme:dark){body::before{background:radial-gradient(55% 45% at 15% 10%,#3a2c8f 0,transparent 70%),radial-gradient(50% 45% at 90% 25%,#13527a 0,transparent 70%),radial-gradient(70% 55% at 40% 100%,#4b1e6b 0,transparent 70%),#0b1024}}\na{color:var(--brand);text-decoration:none;font-weight:600}\nbutton,input,select{font:inherit;color:inherit}\nbutton{border:0;cursor:pointer}\n.wrap{max-width:960px;margin:auto;padding:16px 16px 60px}\n.top{position:sticky;top:8px;z-index:10;display:flex;align-items:center;justify-content:space-between;gap:10px;margin:8px 0 18px;padding:10px 14px;border-radius:22px;background:color-mix(in srgb,var(--bg) 82%,transparent);-webkit-backdrop-filter:saturate(180%) blur(24px);backdrop-filter:saturate(180%) blur(24px);box-shadow:var(--shadow)}\n.logo{display:flex;align-items:center;gap:10px;font-weight:700;font-size:17px;color:var(--text)}\n.logo i{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;background:#101C40;color:#fff;font-style:normal;font-size:18px;overflow:hidden;box-shadow:inset 0 0 0 .5px rgba(255,255,255,.18)}.logo i svg{width:100%;height:100%;display:block}\n.card{background:var(--card);border-radius:22px;padding:18px;box-shadow:var(--shadow);min-width:0}\n.muted{color:var(--muted)}\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:10px 18px;border-radius:99px;background:var(--fill);color:var(--text);font-weight:650;font-size:15px;transition:transform .15s,opacity .2s;white-space:nowrap}\n.btn:active{transform:scale(.96)}.btn:disabled{opacity:.5}\n.btn.primary{background:var(--brand);color:#fff}.btn.danger{color:var(--danger)}.btn.sm{padding:7px 13px;font-size:13.5px}\n.input{width:100%;padding:12px 14px;border-radius:14px;border:0;background:var(--fill);outline:0;font-size:16px;min-width:0}\n.input:focus{box-shadow:0 0 0 3px rgba(0,122,255,.25)}\n.input::placeholder{color:var(--muted);opacity:.7}\nlabel.f{display:block;margin:12px 0 6px;font-size:13px;font-weight:600;color:var(--muted)}\n.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}\n.notice{padding:11px 13px;border-radius:14px;background:var(--fill);font-size:13.5px;color:var(--muted);line-height:1.6}\n.err{color:var(--danger);font-size:13.5px;min-height:20px;margin-top:8px}\n.toast{position:fixed;left:0;right:0;top:16px;margin:auto;width:max-content;max-width:calc(100% - 32px);padding:10px 16px;border-radius:18px;background:var(--card);-webkit-backdrop-filter:blur(24px);backdrop-filter:blur(24px);box-shadow:var(--shadow),0 10px 30px rgba(0,0,0,.15);font-weight:600;font-size:14px;z-index:99;transition:opacity .3s,transform .3s}\n.toast.hide{opacity:0;transform:translateY(-10px);pointer-events:none}\n.hidden{display:none!important}\n.dot{width:9px;height:9px;border-radius:50%;background:#aaa;display:inline-block;flex:none}.dot.on{background:var(--ok)}.dot.off{background:var(--danger)}\nh1,h2,h3{letter-spacing:-.02em;margin:0}\n\n/* 顶栏上面那一条：往上滚的内容在这里淡出，不会从顶栏上方露出来 */\nbody::after{content:\"\";position:fixed;left:0;right:0;top:0;height:calc(env(safe-area-inset-top) + 34px);z-index:9;pointer-events:none;background:linear-gradient(var(--bg) 45%,color-mix(in srgb,var(--bg) 0%,transparent))}\nh2,.sech{scroll-margin-top:90px}\n/* 反馈进度条：反馈成功 → 开发人员已收到 → 已修复 / 无法修复（只显示这三段，补充说明写在下面） */\n.fsteps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin:6px 0 4px}\n.fsteps>div{position:relative;display:flex;flex-direction:column;align-items:center;text-align:center;min-width:0}\n.fsteps>div+div::before{content:'';position:absolute;top:10px;right:calc(50% + 15px);width:calc(100% - 30px);height:3px;border-radius:2px;background:var(--line)}\n.fsteps>div.on::before{background:var(--ok)}.fsteps>div.bad::before{background:var(--danger)}\n.fsteps i{width:23px;height:23px;border-radius:50%;display:grid;place-items:center;font-style:normal;font-size:12px;font-weight:700;background:var(--fill);color:var(--muted)}\n.fsteps .on i{background:var(--ok);color:#fff}.fsteps .bad i{background:var(--danger);color:#fff}\n.fsteps .cur i{box-shadow:0 0 0 4px color-mix(in srgb,var(--ok) 22%,transparent)}.fsteps .bad.cur i{box-shadow:0 0 0 4px color-mix(in srgb,var(--danger) 22%,transparent)}\n.fsteps b{display:block;font-size:12.5px;font-weight:600;margin-top:7px;line-height:1.3;word-break:keep-all}\n.fsteps .off b{color:var(--muted);font-weight:500}.fsteps .bad b{color:var(--danger)}\n\n.doc h1{font-size:28px;margin:18px 0 4px}.doc .sub{color:var(--muted);font-size:13.5px;margin:0 0 18px}\n.doc h2{font-size:19px;margin:28px 0 10px}.doc p,.doc li{font-size:14.5px;line-height:1.8}.doc ul,.doc ol{padding-left:22px;margin:6px 0}.doc .lead{padding:12px 14px;border-radius:14px;background:var(--fill);font-size:14px;line-height:1.75}\nfooter{margin-top:40px;text-align:center;color:var(--muted);font-size:13px}\n</style></head><body><div class=\"wrap doc\">\n<div class=\"top\"><a class=\"logo\" href=\"/\"><i><svg viewBox=\"0 0 100 100\" fill=\"none\" aria-hidden=\"true\"><path d=\"M41.91 24.45A29 29 0 1 0 75.55 58.09A24 24 0 0 1 41.91 24.45Z\" fill=\"#F4F1EA\"/><path d=\"M62.6 21.4A17 17 0 0 1 78.6 37.4\" stroke=\"#FFB547\" stroke-width=\"4\" stroke-linecap=\"round\" fill=\"none\"/><circle cx=\"63\" cy=\"37\" r=\"7\" fill=\"#FFB547\"/></svg></i>路由器面板</a><div class=\"row\"><a class=\"btn sm\" href=\"/privacy\">隐私政策</a><a class=\"btn sm primary\" href=\"/app\">登录</a></div></div>\n\n<h1>用户须知</h1>\n<p class=\"sub\">适用于本网站（官网账号）和托管服务。版本：2026 年 11 月 14 日（对应面板 v5.0）</p>\n<p class=\"lead\">使用路由器面板的官网账号和托管服务之前，请先读完下面这些要点。完整的权利和责任以<a href=\"/terms\">《用户使用协议》</a>为准，数据怎么存、存多久见<a href=\"/privacy\">《隐私政策》</a>。</p>\n\n<h2>一、路由器面板是什么</h2>\n<ol>\n<li>路由器面板是一个装在 OpenWrt 路由器上的<b>手机控制面板</b>：看节点、设备、流量、测速、断线记录，定时断网、推送提醒、云端备份等；AI 版还可以把路由器接到 Claude，用对话管理。代码在 <a href=\"https://github.com/wznwzn123/openwrt-claude-panel\" rel=\"noopener\">GitHub</a> 开源（MIT 许可证）。</li>\n<li>它<b>不是</b> OpenWrt、OpenClash 或其他代理插件、Cloudflare、Anthropic 的官方产品，和它们没有隶属或合作关系。</li>\n<li>有两种用法：<b>托管版</b>由本网站开通专属网址，在外面也能打开面板；<b>自建版</b>用你自己的 Cloudflare 账号和域名，或者只在家里局域网用，数据都在你自己那里，本须知里关于托管服务的部分不适用。</li>\n</ol>\n\n<h2>二、官网账号</h2>\n<ol>\n<li>用邮箱注册，密码至少 8 位。开通了邮件服务时，注册和找回密码要填发到邮箱的验证码。一个邮箱只能注册一个账号。</li>\n<li>账号用来绑定你的路由器、领取试用码、拿新手机的登录码、申请续期和查看自己的反馈。<b>账号里不保存路由器的登录密钥。</b></li>\n<li>账号页能看到哪些设备登录着你的账号，可以单独退出或一键退出其他所有设备；有新设备登录时会发邮件提醒你；改密码后其他设备上的登录会全部退出。</li>\n<li>请不要把密码告诉别人，也不要和其他网站用同一个密码。</li>\n<li>可以在账号页自己注销账号（要输入密码）。注销后 30 天内可以联系我们恢复，之后彻底删除；路由器本身不受影响。</li>\n</ol>\n\n<h2>三、托管服务的开通、到期和删除</h2>\n<ol>\n<li>托管服务用<b>邀请码</b>开通；新注册的账号可以领一次 7 天试用码。到期前 3 天会推送提醒，可以输入续期码续期，或者在账号页「申请续期」等审核。</li>\n<li>到期后专属网址会暂停，续上马上恢复；<b>暂停超过 30 天会被彻底删除</b>。路由器 90 天没上线会放进回收站，30 天后彻底删除。</li>\n<li>在路由器上运行卸载命令（<code>cmcp-uninstall</code>），这台路由器的专属网址和云端数据会马上删除。</li>\n<li>为了服务安全，我们可以停用被滥用、被盗用或者违反使用规范的邀请码、专属网址和账号。</li>\n</ol>\n\n<h2>四、你的路由器和数据</h2>\n<ol>\n<li>路由器的设置和上网情况<b>留在你的路由器上</b>，上网记录不会上传。面板的请求经 Cloudflare 隧道直接到你的路由器，托管服务的程序不经手、不记录。</li>\n<li><b>登录地址等于路由器的最高权限</b>：面板能改设置、能执行命令。登录地址只在自己手机上打开，不要截图分享；觉得泄露了，马上在面板「系统操作」里换登录密钥。</li>\n<li>云端备份里是路由器的全部设置（包括 Wi-Fi 密码、宽带账号、面板登录密钥）。建议开启加密，开启后托管服务只存看不懂的密文。</li>\n<li>你在面板里「实时联系开发者」、问题反馈、报告问题时写的内容和截图，会发到托管服务，用来回复和修问题。请不要在里面写密码、登录地址这些密钥。</li>\n<li>5.0 起，面板的程序出错时会把错误信息、手机类型和屏幕大小发给我们（不带设置、密钥和上网内容）；路由器取公告时带一个随机的匿名编号，用来统计公告的收到和查看情况。</li>\n<li>具体存了哪些数据、存多久、交给了谁，见<a href=\"/privacy\">《隐私政策》</a>。</li>\n</ol>\n\n<h2>五、使用规范</h2>\n<p>请不要用路由器面板和托管服务做下面这些事：</p>\n<ul>\n<li>未经允许管理别人的路由器、查看别人的上网情况；</li>\n<li>攻击或者试图绕过本网站和托管服务的安全措施，暴力猜测密码、登录码和编号；</li>\n<li>批量注册账号、倒卖或滥用邀请码、试用码；</li>\n<li>违反你所在地的法律法规，或者侵犯他人的合法权益。</li>\n</ul>\n<p>面板的「暂停上网」等功能可能用在家人、孩子的设备上，要不要用、对谁用，请你自己决定并告知相关的人。</p>\n\n<h2>六、服务说明</h2>\n<ol>\n<li>托管服务依赖 Cloudflare、GitHub、邮件和推送等第三方服务，可能因为维护、网络或第三方故障暂时用不了。这个项目由一个人维护，功能会持续调整。</li>\n<li>断电断网判断、到期提醒、推送等只作为提醒参考。路由器的设置改动由你自己决定，改之前建议先在面板里做一次备份。</li>\n</ol>\n\n<h2>七、联系我们</h2>\n<p>有问题、建议，或者要查询、删除自己的数据：在面板里「实时联系开发者」，或者用<a href=\"/security#report\">报告表单</a>（不用登录）。</p>\n\n<footer><a href=\"/\">首页</a> · <a href=\"/notice\">用户须知</a> · <a href=\"/terms\">用户使用协议</a> · <a href=\"/privacy\">隐私政策</a> · <a href=\"/security\">安全说明</a> · <a href=\"/app\">账号</a> · <a href=\"https://github.com/wznwzn123/openwrt-claude-panel\" rel=\"noopener\">GitHub</a></footer>\n</div></body></html>\n";
